var GH_BASE32='0123456789bcdefghjkmnpqrstuvwxyz';
function ghEncode(lat, lon, precision){
  if(typeof lat!=='number'||typeof lon!=='number'||isNaN(lat)||isNaN(lon))
    return { value:null, error:'坐标必须是数字' };
  if(lat<-90||lat>90) return { value:null, error:'纬度须在 [-90, 90]' };
  if(lon<-180||lon>180) return { value:null, error:'经度须在 [-180, 180]' };
  var p=Math.floor(precision||9);
  if(p<1||p>12) return { value:null, error:'精度须在 1-12' };
  var latR=[-90,90], lonR=[-180,180], hash='', bit=0, ch=0, even=true;
  while(hash.length<p){
    if(even){
      var mid=(lonR[0]+lonR[1])/2;
      if(lon>=mid){ ch=(ch<<1)|1; lonR[0]=mid; } else { ch=ch<<1; lonR[1]=mid; }
    } else {
      var mid2=(latR[0]+latR[1])/2;
      if(lat>=mid2){ ch=(ch<<1)|1; latR[0]=mid2; } else { ch=ch<<1; latR[1]=mid2; }
    }
    even=!even;
    if(++bit===5){ hash+=GH_BASE32[ch]; bit=0; ch=0; }
  }
  return { value:hash, error:null };
}
function ghBounds(hash){
  var s=String(hash).toLowerCase();
  if(!s.length) return { value:null, error:'geohash 为空' };
  var latR=[-90,90], lonR=[-180,180], even=true;
  for(var i=0;i<s.length;i++){
    var idx=GH_BASE32.indexOf(s[i]);
    if(idx<0) return { value:null, error:'非法字符: '+s[i] };
    for(var b=4;b>=0;b--){
      var bit=(idx>>b)&1;
      if(even){
        var mid=(lonR[0]+lonR[1])/2;
        if(bit) lonR[0]=mid; else lonR[1]=mid;
      } else {
        var mid2=(latR[0]+latR[1])/2;
        if(bit) latR[0]=mid2; else latR[1]=mid2;
      }
      even=!even;
    }
  }
  return { value:{ latMin:latR[0], latMax:latR[1], lonMin:lonR[0], lonMax:lonR[1] }, error:null };
}
function ghDecode(hash){
  var b=ghBounds(hash);
  if(b.error) return b;
  var v=b.value;
  return { value:{ lat:(v.latMin+v.latMax)/2, lon:(v.lonMin+v.lonMax)/2,
    latErr:(v.latMax-v.latMin)/2, lonErr:(v.lonMax-v.lonMin)/2 }, error:null };
}
function ghNeighbor(hash, dLat, dLon){
  var d=ghDecode(hash);
  if(d.error) return d;
  var v=d.value;
  var nlat=v.lat+dLat*v.latErr*2, nlon=v.lon+dLon*v.lonErr*2;
  if(nlat>90||nlat<-90) return { value:null, error:'越过极点' };
  if(nlon>180) nlon-=360;
  if(nlon<-180) nlon+=360;
  return ghEncode(nlat, nlon, String(hash).length);
}
function ghNeighbors(hash){
  var dirs={ n:[1,0], ne:[1,1], e:[0,1], se:[-1,1], s:[-1,0], sw:[-1,-1], w:[0,-1], nw:[1,-1] };
  var out={}, k;
  for(k in dirs){
    var r=ghNeighbor(hash, dirs[k][0], dirs[k][1]);
    if(r.error) return { value:null, error:k+': '+r.error };
    out[k]=r.value;
  }
  return { value:out, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { GH_BASE32:GH_BASE32, ghEncode:ghEncode, ghDecode:ghDecode,
    ghBounds:ghBounds, ghNeighbor:ghNeighbor, ghNeighbors:ghNeighbors };
}
if (typeof window !== 'undefined') {
  window.GeohashForgePure = { GH_BASE32:GH_BASE32, ghEncode:ghEncode, ghDecode:ghDecode,
    ghBounds:ghBounds, ghNeighbor:ghNeighbor, ghNeighbors:ghNeighbors };
}
